    void execute() {
        System.out.print("Service:" + getTitle());
    }
    abstract String getTitle();
}
class FormalGreeting extends GreetingService {
    @Override
    String getTitle() {
        return "Formal";
    }
}
public class Main {
    public static void main(String[] args) {
        GreetingService gs = new FormalGreeting();
        gs.execute();
    }
}
```

